# -*- coding: utf-8 -*-
"""Stage 3 merge for report 60 (Mindway)."""
import json
C = {x["id"]: x for x in json.load(open("Tools/prd_ledger/canonical.json"))}
def ext(cid, text):
    if text not in C[cid]["statement"]: C[cid]["statement"] += text
def add(cid, section, title, statement):
    if cid in C: return
    C[cid] = dict(id=cid, title=title, statement=statement, section=section, cards=[], reports=[], merged_from=[])

add("C277", "product-rule", "Price the paid tier against what the phone already gives away — a paywall that sells task slots, reminders or a checklist is compared to Apple Reminders, Notes and paper, and loses",
    "Report 60 (Mindway, 216 reviews): price objections are relative, not absolute — 13 reviewers (6.02%, mean 1.69, no 4★ or 5★ among them) reject the price by comparing it to a substitute they already own, and 6 (2.78%) name it: Apple Reminders, Notes, Calendar, a paper planner — '8€/WOCHE für einen Tagesplaner, den man sich auch selbst im Kalender bauen kann. Frech.' (€8 a week for a day planner you could build in your calendar. Cheeky.); 'einfach zu teuer dafür dass ich das auch gratis in meinen Notizen machen kann'; 'paper planner is cheaper than this LOL'; 'Just use your remind app it's the same thing'. The report's reading: 'the competitive set Mindway is being priced against is not other habit apps — it is the free tools already on the phone', and a count-based paywall ('you have used your 2 free tasks') invites exactly that comparison because task slots are what those tools give away, whereas guided routines, progress history and a self-care library are not comparable to Reminders — 'the corpus shows Mindway losing a fight it chose' (D2: sell the outcome, not the task slots). Related: [[C214]] (a bare checklist cannot carry a premium price), [[C133]] (gate on capability, not quantity), [[C004]] (price against subscription competitors).")

ext("C214", " Report 60 (Mindway): the same verdict from buyers — 10 (4.63%, mean 1.50), five of them confirmed payers, say the paid product is 'nothing more than preloaded to-do lists'; 'just a suggestion list'; 'basically just a load of lists and reminders'; 'I cannot believe I spent $40 to use this app for one day' — and six non-buyers price it against Reminders, Notes, Calendar and paper ([[C277]]).")
ext("C133", " Report 60 (Mindway): the purest count gate in the ledger — a free tier of roughly 1–3 tasks in a daily routine planner (M_PAYWALL_BLOCK 19, 8.80%, mean 1.63, 13 of 19 at 1★, in six languages: 'I wanted to add third task to do and I can't do it without paying'; 'you need to pay money to just write some freaking habits'; 'quería organizar mi día y no puedo ya que solo por hacer algo me pide pagar'); the cap sits below the app's own minimum viable use — 'a daily routine of two tasks is not a routine, so the free tier cannot demonstrate the thing the paid tier sells' — and it is the only major theme still growing in the 2026 tail (5.33% → 8.66% → 28.57% of period); D1: gate on depth — multiple routines, history, advanced recurrence, the guided content — rather than on count.")
ext("C147", " Report 60 (Mindway): 'the decision the corpus forces' — move the paywall behind first value: the value users report (structure 15, habit outcomes 12, wellbeing 9, mean 4.79) takes days to appear and the current design charges before any of it can happen (ad → questionnaire → 'asked for money right away'); the three reviewers who met the cost as optional averaged 4.33★, the thirteen who met it as a wall 1.69★ — 'how the cost is encountered, not the cost itself, determines the rating'; every one of the 13 confirmed payers wrote a negative review; E1: raise the free cap to a full day's routine (8–10 tasks) for a randomized cohort; E2: replace the count-based paywall with a time-based one — full app, 7 days, no card ('I wish it would of let me try it out first').")
ext("C182", " Report 60 (Mindway): the pre-value paywall follows a mandatory onboarding questionnaire — 'it was really strange like answering a questionnaire. Then it asked for money right away' (1★); 'Stop playing games and get to plan'; 19 blocked plus 3 interrupted (8.80% + 1.39%) are the largest upgrade barrier.")
ext("C111", " Report 60 (Mindway): the sequence ad → onboarding questionnaire → price is what the two ad-sourced reviewers (both 1★) and the scam accusers describe — 'Put the price next to your product in the App Store. Its the only correct way to go about selling a product above board'.")
ext("C218", " Report 60 (Mindway): M_MISLEADING_ADVERT 5 (all 1★: 'Click bait'; 'Not set up as advertised'; 'is it free? No. So Change to paid.'; 'it said it was free') and both ad-sourced reviewers at 1★ — F4: state the subscription price and the free-tier limit in the App Store listing and in the first ad frame, which 'removes the click bait / it said it was free class of review entirely'.")
ext("C181", " Report 60 (Mindway): 'Put the price next to your product in the App Store' — a paywalled app advertised as a free planner produced five misleading-advert reviews and five scam accusations, every one 1★.")
ext("C029", " Report 60 (Mindway): billing operations failing is 'a store-risk problem, not a pricing problem' — 11 of 216 (5.09%, mean 1.27, 10 of 11 US): charged for a year without subscribing ('this needs to be reported and i want my money back'), charged after cancelling with screenshots of inactive status, a $0.99 'free trial' billed $39.99 within hours, a 3-day trial that billed a week after cancelling on day two, monthly implied but the whole year drafted; the corpus cannot prove the charges were unauthorized, but eleven users could not tell what they had agreed to or how to get out, and seven of them used a public review as their support channel; all 13 confirmed payers are the only source of every refund, cancellation and surprise-charge report — 'the corpus contains no post-purchase success story at all'.")
ext("C112", " Report 60 (Mindway): M_CANCEL_DIFFICULTY 4 (mean 1.00) plus one who cancelled and was charged anyway — 'There is no way to cancel'; 'Please help me unsubscribe'; 'I am getting no help and stopping the subscription'; an AU reviewer still asking how to cancel 14 months after the first report; F1: make cancellation one tap from the main screen and confirm it in writing — 'the cheapest star recovery available' and 'the highest-severity item in the report'.")
ext("C109", " Report 60 (Mindway): three distinct trial failures from three users — a $0.99 paid trial converting to $39.99 within hours ('with NO EXCEPTIONS OF A REFUND'), a '3 day free trial' that billed a week after cancelling on day two (a 4★ that would otherwise be 5★), and no trial offered at all before purchase ('I'm just out the money now') — 'a flow problem, not three user errors'; F2: audit the trial-to-charge flow end to end.")
ext("C177", " Report 60 (Mindway): 'When purchasing, it implies the option of monthly billing, but auto drafts the whole year' (1★, 'It seems scammy'); the annual is chosen to escape the weekly ('paid the $40 annual to avoid $7/week') and then regretted — plan clarity at purchase is one of the five paid-user issues; F2 includes the monthly-vs-annual selection screen.")
ext("C190", " Report 60 (Mindway): weekly pricing reads as expensive — $7/week and €8/week both cited with outrage ('8€/WOCHE… Frech'), and the annual is chosen to escape the weekly; E3: offer a cheap one-time purchase or a low monthly tier alongside the weekly — nobody objects to paying something (M_COST_NOTED 3 at 4.33★).")
ext("C065", " Report 60 (Mindway): the extreme case — 13 explicit payers (6.02%), mean 1.38, 11 of 13 at 1★, zero at 5★; 'not one paying reviewer describes getting value for the money… the most consequential single number in the report'; every refund request, cancellation failure and unexpected-charge report in the corpus comes from this segment; five of thirteen say the paid product is a list, not a tracker; the responsible reading — the segment is biased toward the aggrieved — still leaves 'the only payer voices the store shows prospective buyers are 1★'.")
ext("C212", " Report 60 (Mindway): four refund requests, all 1★, all US, all after an annual charge — refused ('NO EXCEPTIONS OF A REFUND'), no route found, 'this needs to be reported', 'I wish I could get my money back'.")
ext("C036", " Report 60 (Mindway): seven reviewers (3.24%, mean 1.43) used a 1★ public review as a help desk — 'the absence of a visible support path', six of the seven about money; the one who tried the proper route ('asked this question of the developer and awaiting the reply') rated 3★ where the other six went straight to 1★ — 'the one payer who found a support route rated the app two stars higher than the ones who didn't'; F3: put an in-app support route in front of the review prompt, and answer it — seven support tickets became permanent public 1★ reviews.")
ext("C215", " Report 60 (Mindway): five of thirteen payers used a 1★ review as their support channel; 'I am getting no help and stopping the subscription' — a support route that is slower than the review prompt turns billing tickets into permanent 1★ reviews.")
ext("C150", " Report 60 (Mindway): 'Good but forcing me to rate😅🙄 / ITS FORCING MEE' (5★); 28 reviews (12.96%) say the reviewer has only just started ('I'm ready / I'm excited'; 'Just getting started, figuring it out!'; 'Lo voy descargando y ya me esta gustando') — 20 of the 128 5★; two 1★ with neutral text ('To soon to say'; 'Not sure about app yet') look like users rating the experience of being asked to rate; D6: stop harvesting ratings from users who have not used the app — a prompt after a routine completed on the fifth consecutive day would produce fewer, better, more durable reviews (E5).")
ext("C094", " Report 60 (Mindway): a rating prompt fired on first session plus a paid acquisition push produced a 4-month burst — 98 of 216 (45.37%) in 2025-03/04, mean 4.12, 63 at 5★, from 32 storefronts, 52.76% of them content-free — that raised the mean 0.62 stars while adding almost no product evidence; when the push stopped, volume fell from 59 a month to 2 and the mean fell to 3.21, below launch level: 'the burst bought a rating, not a reputation, and it decayed the moment it stopped'; the modal 5★ is nine characters ('Love it') and only 37 of 128 5★ (28.91%) state a reason connected to using the product.")
ext("C076", " Report 60 (Mindway): a 45% two-month burst of very short, very positive, mostly non-English reviews with no duplicated authors or bodies — read as a paid acquisition push plus a first-session rating prompt rather than a farm — is disclosed as 'the single most distorting structural fact in the dataset'; the mean it bought decayed to 3.21 within weeks of the push ending.")
ext("C093", " Report 60 (Mindway): 'every 5 seconds it keeps brining up these Hey pay me now Pop Ups… let me do my activities and move on with my life' (1★); 'It keeps saying do you want a free trial for something'; 'it won't allow me make a plan without showing free trial vip' — an upsell that fires inside the task the user came to do; F5: stop firing the upsell inside an in-progress task — 'a description of a broken interaction, not of a pricing disagreement'.")
ext("C240", " Report 60 (Mindway): the upsell interrupts the planning task itself — three reviewers (1.39%, mean 1.33) describe pop-ups 'every 5 seconds' while building a routine ([[C093]]).")
ext("C137", " Report 60 (Mindway): the counter-case — a paywall shown at the moment of need is fine only if the need is real; here the 'need' is the third task of a routine, so the moment-of-need paywall is the wall itself (19 blocked at 1.63★).")
ext("C234", " Report 60 (Mindway): the paid product has no progress view at all — 'thought this would give more feedback on completion percentage - tracking consistency. It's just a basic to do list'; 'very little flexibility or encouragement'; no reviewer in 216 describes a streak, chart, score or progress view; D3: build the tracking layer — 'the largest non-pricing gap in the report' and the capability that justifies a subscription because it cannot be replicated in Notes (E4: completion %, current streak, 30-day grid).")
ext("C012", " Report 60 (Mindway): a routine planner sold without any consistency view is judged 'just a to-do list' by 10 reviewers including 5 payers; the minimal fix proposed is a completion % plus current streak plus a 30-day grid (E4).")
ext("C024", " Report 60 (Mindway): the absence of streaks or any progress view is what payers name when they call the product under-built — the 'encouragement' and 'tracking consistency' they expected and did not get.")
ext("C043", " Report 60 (Mindway): recurrence limited to daily / weekly / monthly is the largest functional request — R_REPEAT_OPTIONS 3 and R_CUSTOM_TASKS 4 of only 10 requests: 'I don't need to flip my mattress every month, but that's the only option I'm given'; hourly hydration, every 2 weeks, every 6 months, haircuts; plus fixed 28/38-day programme pacing the user cannot control ('neden tüm planları kendimiz hemen o gün yapamıyoruz'); D5: fix the recurrence model before adding anything else — four of ten requesters ask for flexibility in different words.")
ext("C118", " Report 60 (Mindway): preset routine packs (self-care, hair care, exercise, chores, hydration) and a self-care guide are the praised entry point (P_CONTENT_PACKS 5, 4.80★: 'having a guide to which to refer'; 'rehberle çok yardım ettiler') and the inferred paid asset — but packs loaded by default are also a clean-up burden ('otherwise you would spend all day deleting tasks', a payer; 'It is overwhelming to set up tasks in the beginning'); E6: a bulk-remove-pack control and a first-run 'pick one of three ready-made days'; custom task creation is limited or gated and is the most-requested capability ('I wish there was a way to personalize or make my own').")
ext("C203", " Report 60 (Mindway): a mandatory onboarding questionnaire followed immediately by the paywall ('answering a questionnaire. Then it asked for money right away'; 'Stop playing games and get to plan') and preset packs the user must delete rather than a routine they author; one reviewer asks for '3 complete day schedules' to pick from so 'adding and subtracting would not be so overwhelming'.")
ext("C042", " Report 60 (Mindway): an app named for ADHD — 4 of 216 (1.85%) mention it, 3 praise the fit at 5.00 with zero ADHD-related complaints, across US, TR and CH: 'This app helps me a lot since I was suffering from ADHD from my childhood. It helps me organize my day'; 'As someone with ADHD. This helps me stay on task instead of getting distracted'; 'Parfait pour un TDAH'; and 'I don't think I have ADHD but it really helps' — the positioning reaching beyond its target rather than narrowing the market; D4: commit to the ADHD positioning and say so in the listing — the only differentiated claim the corpus supports and one Reminders / Notes / Calendar cannot match.")
ext("C183", " Report 60 (Mindway): organisation and structure is the most-cited benefit (15, 6.94%, mean 4.80, 13 at 5★): 'I used to be a mess, today I'm organised' (IL); 'Now I have a regular plan' (TR); 'You plan what you're gonna do at the next day'; the ADHD reviewers credit exactly this ('helps me stay on task instead of getting distracted').")
ext("C213", " Report 60 (Mindway): an ADHD-positioned routine planner whose subscription four users could not cancel and whose paid trial billed within hours — the positioning makes the billing failures a betrayal of the audience it names.")
ext("C134", " Report 60 (Mindway): the marketable asset is concrete habit outcomes in reviewers' own words — 'makes me drink more water'; 'We will drink 4 glasses of water each day'; 'even got me to stretch'; 'This actually helps me with my chores, even though I'm seven'; 'It made me calm'; 'THIS APP MAKES ME FEEL SO MUCH BETTER' — 43 (19.91%) at 4.79★, 'Mindway's value proposition translates' across ten languages, while the listing and the paywall sell task slots.")
ext("C140", " Report 60 (Mindway): outcomes named are hydration, workouts, tidying, stretching, getting out of bed and chores — a routine planner is used as a generic self-care tracker.")
ext("C067", " Report 60 (Mindway): 'Makes me hydrated makes me work out in a lot'; 'work out, drink more water, make my bed, do good in school, and tidy up my room' — health routines are the concrete outcomes named.")
ext("C062", " Report 60 (Mindway): the US (101 of 216) is simultaneously the biggest market, the only paying market in evidence (11 of 13 payers) and the angriest (3.56★; 26 of the 38 1★; 10 of 11 billing failures) — 'Americans complain about value; everyone else complains about access'; a definitional high-spend group (178 reviews) rates 0.62 lower, complains about money half again as often and holds every confirmed payer, while the rest-of-world 4.11 mean is 'users who never got far enough in to be disappointed expensively'.")
ext("C231", " Report 60 (Mindway): the US vs rest-of-world split is a funnel-stage split — the US has bought and been disappointed (under-built 7.92% vs 1.74%, billing 9.90% vs 0.87%), the rest of the world has been stopped at the door (paywall cap 11.30% vs 5.94%); whether the billing rate improved after 2024 or the US share of reviews simply fell (85.3% → 26.8%) cannot be separated from review text (Q3).")
ext("C027", " Report 60 (Mindway): the paywall complaint appears in 13 storefronts and 6 languages with the same structure and the benefit claims in near-identical words across ten languages — 'Mindway's value proposition translates'; 59 bodies (27.31%) are non-English across 22 storefronts, and 90 of 125 polled storefronts (Japan, Korea, Spain, India, Russia, Indonesia, Philippines) returned zero reviews.")
ext("C071", " Report 60 (Mindway): after a two-month acquisition burst the app produced roughly one review a month for 15 months with two four-month silences, and no reviewer in 750 days reports a problem being resolved (is_edited false on all 216) — the 2026 tail is 28.57% paywall complaints and zero benefit claims.")
ext("C196", " Report 60 (Mindway): benefit claims (habit outcome, motivation, wellbeing) peak in the burst period and vanish to zero in the 14-review tail while paywall complaints rise to 28.57% — 'the corpus's least comfortable pattern' for a subscription product.")
ext("C185", " Report 60 (Mindway): design praise sits beside price rejection in the same sentences — 'Es ist eigentlich sehr schön gemacht und gestaltet aber einfach zu teuer'; 'It is a good app well designed but cost abit of money' — P_DESIGN has a mean of 3.00; one dissent finds the cute styling 'too bubbly… better off to be more neutral and simple', and the report says do not redesign on that one complaint.")
ext("C117", " Report 60 (Mindway): 'LOVED THE SLIMY MASCOT' (one 5★); the cute / bubbly tone draws one 2★ dissent — n=1 each way.")
ext("C031", " Report 60 (Mindway): only 2 of 216 (0.93%) report a crash, both within five days in 2024-10 and never again — consistent with one bad build; 'the product is barely reported as broken', which is what makes the monetization findings unambiguous.")
ext("C005", " Report 60 (Mindway): the competitors reviewers name are not habit apps but Apple Reminders, Notes, Calendar and a paper planner (6, 2.78%) — the free tools already on the phone ([[C277]]).")
ext("C189", " Report 60 (Mindway): five explicit warn-offs ('Don't waste your money'; 'Don't ever download this app'; 'Don't download if you need for a routine'), all 1★, remain visible on the listing at the point of decision — an upgrade barrier the report counts alongside billing trust damage.")
ext("C045", " Report 60 (Mindway): 'There is no folder system. I can't categorize my reminders' (one 3★ request).")
ext("C075", " Report 60 (Mindway): 'It is overwhelming to set up tasks in the beginning' — a first-run 'pick one of three ready-made days' is the proposed fix (E6); a how-to for bulk-removing unwanted preset tasks is requested by a payer.")
ext("C171", " Report 60 (Mindway): time entry on a 24-hour clock only, no AM/PM option — 'This confuses me a lot'; F6: add AM/PM time entry, 'one review, one line of work, and it is the only reported input-level usability defect in the corpus' — respect the user's locale time format.")
ext("C064", " Report 60 (Mindway): price points $7/week, €8/week, $39.99–40/year, '$60 a year', a $0.99 paid trial; 'a bit expensive for something I could do myself' (payer, 3★); the objection is relative to free substitutes, not to a number ([[C277]]).")
ext("C193", " Report 60 (Mindway): with a free tier of 1–3 tasks there is no usable free tier to land on — a lapsed or refused subscriber has nowhere to go but the wall.")
ext("C217", " Report 60 (Mindway): 'It's just a basic to do list' — the absence of any metric at all (no completion %, no consistency view) is read as the product being unfinished.")

